  'course.second-order.doc.bk.eig.title': 'Eigenvalue problem',
  'course.second-order.doc.bk.eig.what': 'A nonzero solution φ exists when the determinant vanishes. It is a polynomial in λ; its positive roots, in increasing order, are the critical factors.',
  'course.second-order.doc.bk.mode': 'Mode',
  'course.second-order.doc.bk.modeCaption': 'Mode {k}, λ = {lambda} (shape, not to scale).',
  'course.second-order.doc.bk.modes.title': 'Buckling modes',
  'course.second-order.doc.bk.modes.what': 'For each λᵢ, the vector φ that K(λᵢ) annihilates is the shape in which the structure buckles.',
  'course.second-order.doc.bk.keff.title': 'Critical load and effective length of each member',
